// firebase-messaging-sw.js
// Imported into the main PWA service worker generated by workbox.

importScripts('https://www.gstatic.com/firebasejs/10.14.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.14.0/firebase-messaging-compat.js');

// Extract config params from script URL query parameters if present, or fallback to location params
const urlParams = new URLSearchParams(self.location.search);

firebase.initializeApp({
  apiKey: urlParams.get('apiKey') || self.VITE_FIREBASE_API_KEY || "",
  authDomain: urlParams.get('authDomain') || "kulpslate.firebaseapp.com",
  projectId: urlParams.get('projectId') || "kulpslate",
  storageBucket: urlParams.get('storageBucket') || "kulpslate.firebasestorage.app",
  messagingSenderId: urlParams.get('messagingSenderId') || "112333951852",
  appId: urlParams.get('appId') || "1:112333951852:web:f10c2642d2bdeebe80d949"
});

const messaging = firebase.messaging();

// Handle background notifications
messaging.onBackgroundMessage((payload) => {
  console.log('[firebase-messaging-sw.js] Received background message:', payload);
  
  const notificationTitle = payload.notification?.title || 'Slate Notification';
  const notificationOptions = {
    body: payload.notification?.body || '',
    icon: '/favicon.svg',
    badge: '/favicon.svg',
    data: payload.data || {},
    vibrate: [200, 100, 200]
  };

  // Only show notification if payload.notification is not present,
  // since the Firebase FCM SDK automatically displays a background notification when it is present.
  if (!payload.notification) {
    self.registration.showNotification(notificationTitle, notificationOptions);
  } else {
    console.log('[firebase-messaging-sw.js] Background notification handled automatically by FCM.');
  }
});

// Handle notification click to focus or open app
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If a window is already open, focus it
      for (const client of clientList) {
        if ('focus' in client) {
          return client.focus();
        }
      }
      // Otherwise open a new window
      if (clients.openWindow) {
        return clients.openWindow('/');
      }
    })
  );
});
